(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12 + Math.sin((x+y)*0.008+t*0.4)*8;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.015+t*0.28)*12 + Math.cos((x-y)*0.009-t*0.35)*8;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.5)*8 + Math.cos(sy*0.03+t*0.3)*6;
  const w2y = Math.cos(sy*0.022+t*0.45)*8 + Math.sin(sx*0.028-t*0.35)*6;
  const wx = sx+w2x, wy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.55)*110, 80+Math.cos(t*0.38)*55, 0.075, 2.1, 0.8],
    [320+Math.cos(t*0.48)*105, 160+Math.sin(t*0.65)*55, 0.095, 1.8, 1.2],
    [240+Math.sin(t*0.28+2)*145, 120+Math.cos(t*0.45+1)*95, 0.055, 2.4, 0.6],
    [100+Math.cos(t*0.75+1)*85, 185+Math.sin(t*0.55+3)*65, 0.11, 1.6, 1.4],
    [370+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.85+2)*75, 0.065, 2.7, 0.9],
    [240+Math.cos(t*0.32+5)*125, 210+Math.sin(t*0.5)*85, 0.085, 2.0, 1.1],
    [60+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.7+1)*50, 0.1, 1.4, 1.3],
    [420+Math.cos(t*0.42+2)*60, 220+Math.sin(t*0.58+4)*45, 0.07, 2.5, 0.7]
  ];
  let aS=0, iS=0, cross=0;
  for(let i=0;i<src.length;i++){
    const [sX,sY,f,sp,ph]=src[i];
    const d=Math.sqrt((wx-sX)**2+(wy-sY)**2);
    const a=Math.sin(d*f-t*sp+ph);
    const inh=Math.sin(d*f*0.65+t*sp*0.55+ph*2);
    aS+=a; iS+=inh;
    for(let j=i+1;j<src.length;j++){
      const [sX2,sY2,f2,sp2,ph2]=src[j];
      const d2=Math.sqrt((wx-sX2)**2+(wy-sY2)**2);
      cross+=Math.sin(d*f+t*sp+ph)*Math.sin(d2*f2-t*sp2+ph2)*0.08;
    }
  }
  const act=aS/8, inh=iS/8;
  const bg=(Math.sin(wx*0.035+wy*0.022+t*0.7)+Math.sin(wx*0.028-wy*0.035+t*0.95))/2
    +Math.sin((wx+wy)*0.1+t*2.2)*0.18+Math.sin((wx-wy)*0.085-t*1.8)*0.18
    +Math.sin(wx*0.06+wy*0.04-t*1.3)*0.12;
  const dist=Math.sqrt((wx-cx)**2+(wy-cy)**2), ang=Math.atan2(wy-cy,wx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.4)+Math.sin(dist*0.035+ang*4.5-t*1.1)+Math.sin(dist*0.06-ang*2-t*2))*0.33;
  const voronoi=()=>{
    let md=999;
    for(let i=0;i<6;i++){
      const gx=Math.sin(t*0.2+i*1.05)*80+120+i*60, gy=Math.cos(t*0.25+i*0.8)*50+60+((i%3)*50);
      const d=Math.sqrt((wx-gx)**2+(wy-gy)**2);
      if(d<md)md=d;
    }
    return md;
  };
  const vEdge=Math.max(0,1-voronoi()*0.04);
  const reaction=Math.tanh((act-inh*0.65+bg*0.25+spiral+cross)*2.0);
  const cell=Math.tanh((Math.sin(wx*0.13)*Math.sin(wy*0.13)+Math.sin((wx+wy)*0.09+t)*0.5+Math.sin(wx*0.07-wy*0.11+t*0.6)*0.3)*1.4)*0.25;
  const micro=(Math.sin(wx*0.4+t*3)*Math.sin(wy*0.4-t*2.5))*0.06;
  const blend=reaction*0.65+cell*0.2+vEdge*0.1+micro, v=blend*0.5+0.5;
  const pal=[
    [5,12,52],[12,45,88],[18,95,115],[25,155,135],[120,190,120],
    [220,200,60],[225,140,55],[195,70,60],[140,35,65],[75,18,55],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18+micro*2;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.max(0,reaction)*0.08;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*80))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*120))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*180))|0
  ];
}
